// Extra explanation, examples and practice for each lesson, added around the lesson's own steps.
import { I, C, T } from '../kit.js';

// The answer check cannot turn ł into l, so a typed answer with ł also accepts a copy with plain l.
const unl = (s) => s.replace(/ł/g, 'l').replace(/Ł/g, 'L');
const P = (prompt, pl, explain, accept = []) =>
	T(prompt, pl, explain, [...accept, ...[pl, ...accept].filter((a) => /[łŁ]/.test(a)).map(unl)]);

